<?php require '../includes/conexao.php'; require '../includes/verificar_login.php'; exigir_admin(); $resultados=$pdo->query('SELECT r.*,u.nome FROM resultados r JOIN usuarios u ON u.id=r.usuario_id ORDER BY r.jogado_em DESC')->fetchAll(); $titulo='Resultados'; $root='../'; $home='../dashboard.php'; include '../includes/header.php'; ?><div class="section-heading"><div><div class="eyebrow">Histórico de partidas</div><h1 style="font-size:4rem">Resultados dos alunos</h1></div></div><div class="card"><table><thead><tr><th>Aluno</th><th>Jogo</th><th>Nível</th><th>Pontos</th><th>A/E</th><th>Data</th></tr></thead><tbody><?php foreach($resultados as $r): ?><tr><td><?= htmlspecialchars($r['nome']) ?></td><td><?= htmlspecialchars($r['jogo']) ?></td><td><?= ucfirst($r['dificuldade']) ?></td><td><?= $r['pontuacao'] ?></td><td><?= $r['acertos'] ?>/<?= $r['erros'] ?></td><td><?= date('d/m/Y H:i',strtotime($r['jogado_em'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php include '../includes/footer.php'; ?>
